"""Weekly timesheet rows built from a list of shifts."""

def _name(shift):
    name = shift.worker.strip()
    if not name:
        raise ValueError("blank worker name")
    return name

def _tally(shifts):
    sums = {}
    for shift in shifts:
        name = _name(shift)
        count, mins = sums.get(name, (0, 0))
        sums[name] = (count + 1, mins + shift.span.minutes)
    return sums

def _busiest(sums):
    return sorted(
        sums,
        key=lambda name: (-sums[name][1], name)
    )

def _row(name, count, minutes):
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

# ---
def timesheet_rows(shifts):
    """One line per worker, most hours first."""
    if not shifts:
        raise ValueError("no shifts given")
    sums = _tally(shifts)
    return [_row(name, *sums[name]) for name in _busiest(sums)]

