import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span

def _shift(name, start, end):
    return Shift(name, "mon", Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    # ---
    def test_busiest_first(self):
        rows = timesheet_rows([
            _shift("Ann", 9, 10),
            _shift("Bob", 9, 12),
            _shift("Ann", 13, 14)
        ])
        self.assertEqual(rows, [
            "Bob: 1 shifts, 3.0 hours",
            "Ann: 2 shifts, 2.0 hours"
        ])

    # ---
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    # ---
    def test_blank_name_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([_shift("  ", 9, 10)])
